-- Icaro Ops staff/personnel system.
--
-- Purpose:
--   Introduce game-generated staff candidates and hired company staff.
--
-- Design:
--   - Candidates are people generated by the game.
--   - If hired, they become persistent company staff.
--   - Pilots and technicians have personality parameters and licenses/ratings.
--   - A Cessna 208 passenger flight will require at least:
--       2 hired pilots
--       Commercial Pilot License
--       C208 type rating
--     Technical requirements will be enforced later in flight dispatch/maintenance.
--
-- Run:
--   sudo mysql icaro_ops < db/mysql/074_create_staff_personnel.sql

USE icaro_ops;

START TRANSACTION;

-- For now, focus the game on the player's own base.
-- This keeps rival company data in the DB, but hides their bases from the map
-- because api/public/map/bases.php only returns active rivals.
UPDATE rival_companies
SET is_active = FALSE
WHERE is_active = TRUE;

CREATE TABLE IF NOT EXISTS staff_license_types (
  code VARCHAR(50) NOT NULL,
  name VARCHAR(120) NOT NULL,
  staff_role VARCHAR(30) NOT NULL,
  description VARCHAR(500) NOT NULL,
  is_required_for_commercial_ops BOOLEAN NOT NULL DEFAULT FALSE,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  PRIMARY KEY (code),
  KEY idx_staff_license_types_role (staff_role),
  CONSTRAINT chk_staff_license_types_role
    CHECK (staff_role IN ('PILOT', 'TECHNICIAN'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS staff_candidates (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,

  first_name VARCHAR(80) NOT NULL,
  last_name VARCHAR(80) NOT NULL,
  display_name VARCHAR(180) NOT NULL,

  staff_role VARCHAR(30) NOT NULL,
  status VARCHAR(30) NOT NULL DEFAULT 'AVAILABLE',

  home_region_code VARCHAR(30) NULL,
  preferred_base_icao_code CHAR(4) NULL,

  age_years TINYINT UNSIGNED NOT NULL,
  experience_level VARCHAR(30) NOT NULL,

  fear_score TINYINT UNSIGNED NOT NULL,
  courage_score TINYINT UNSIGNED NOT NULL,
  stress_tolerance_score TINYINT UNSIGNED NOT NULL,
  discipline_score TINYINT UNSIGNED NOT NULL,
  teamwork_score TINYINT UNSIGNED NOT NULL,
  reliability_score TINYINT UNSIGNED NOT NULL,
  ambition_score TINYINT UNSIGNED NOT NULL,
  fatigue_risk_score TINYINT UNSIGNED NOT NULL,

  flight_hours_total INT UNSIGNED NOT NULL DEFAULT 0,
  aircraft_maintenance_hours_total INT UNSIGNED NOT NULL DEFAULT 0,

  salary_per_flight DECIMAL(12,2) NOT NULL DEFAULT 0.00,
  daily_retainer DECIMAL(12,2) NOT NULL DEFAULT 0.00,
  revenue_share_percent DECIMAL(5,2) NOT NULL DEFAULT 0.00,
  currency_code CHAR(3) NOT NULL DEFAULT 'EUR',

  hiring_bonus DECIMAL(12,2) NOT NULL DEFAULT 0.00,
  morale_score TINYINT UNSIGNED NOT NULL DEFAULT 70,

  generated_at_utc TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  expires_at_utc TIMESTAMP NULL,

  PRIMARY KEY (id),
  KEY idx_staff_candidates_role_status (staff_role, status),
  KEY idx_staff_candidates_base (preferred_base_icao_code),
  CONSTRAINT fk_staff_candidates_preferred_base
    FOREIGN KEY (preferred_base_icao_code)
    REFERENCES airports(icao_code)
    ON UPDATE CASCADE
    ON DELETE SET NULL,

  CONSTRAINT chk_staff_candidates_role
    CHECK (staff_role IN ('PILOT', 'TECHNICIAN')),

  CONSTRAINT chk_staff_candidates_status
    CHECK (status IN ('AVAILABLE', 'HIRED', 'EXPIRED', 'REJECTED')),

  CONSTRAINT chk_staff_candidates_scores
    CHECK (
      fear_score BETWEEN 0 AND 100
      AND courage_score BETWEEN 0 AND 100
      AND stress_tolerance_score BETWEEN 0 AND 100
      AND discipline_score BETWEEN 0 AND 100
      AND teamwork_score BETWEEN 0 AND 100
      AND reliability_score BETWEEN 0 AND 100
      AND ambition_score BETWEEN 0 AND 100
      AND fatigue_risk_score BETWEEN 0 AND 100
      AND morale_score BETWEEN 0 AND 100
    ),

  CONSTRAINT chk_staff_candidates_currency
    CHECK (currency_code IN ('EUR', 'USD')),

  CONSTRAINT chk_staff_candidates_compensation
    CHECK (
      salary_per_flight >= 0
      AND daily_retainer >= 0
      AND revenue_share_percent BETWEEN 0 AND 100
      AND hiring_bonus >= 0
    )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS staff_candidate_licenses (
  candidate_id BIGINT UNSIGNED NOT NULL,
  license_code VARCHAR(50) NOT NULL,
  proficiency_score TINYINT UNSIGNED NOT NULL DEFAULT 70,
  issued_at_utc TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  expires_at_utc TIMESTAMP NULL,
  PRIMARY KEY (candidate_id, license_code),
  KEY idx_staff_candidate_licenses_license (license_code),

  CONSTRAINT fk_staff_candidate_licenses_candidate
    FOREIGN KEY (candidate_id)
    REFERENCES staff_candidates(id)
    ON UPDATE CASCADE
    ON DELETE CASCADE,

  CONSTRAINT fk_staff_candidate_licenses_license
    FOREIGN KEY (license_code)
    REFERENCES staff_license_types(code)
    ON UPDATE CASCADE
    ON DELETE RESTRICT,

  CONSTRAINT chk_staff_candidate_licenses_proficiency
    CHECK (proficiency_score BETWEEN 0 AND 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS company_staff (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,

  company_id BIGINT UNSIGNED NOT NULL,
  source_candidate_id BIGINT UNSIGNED NULL,

  first_name VARCHAR(80) NOT NULL,
  last_name VARCHAR(80) NOT NULL,
  display_name VARCHAR(180) NOT NULL,

  staff_role VARCHAR(30) NOT NULL,
  employment_status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE',

  assigned_base_icao_code CHAR(4) NOT NULL,

  age_years TINYINT UNSIGNED NOT NULL,
  experience_level VARCHAR(30) NOT NULL,

  fear_score TINYINT UNSIGNED NOT NULL,
  courage_score TINYINT UNSIGNED NOT NULL,
  stress_tolerance_score TINYINT UNSIGNED NOT NULL,
  discipline_score TINYINT UNSIGNED NOT NULL,
  teamwork_score TINYINT UNSIGNED NOT NULL,
  reliability_score TINYINT UNSIGNED NOT NULL,
  ambition_score TINYINT UNSIGNED NOT NULL,
  fatigue_risk_score TINYINT UNSIGNED NOT NULL,

  flight_hours_total INT UNSIGNED NOT NULL DEFAULT 0,
  aircraft_maintenance_hours_total INT UNSIGNED NOT NULL DEFAULT 0,

  salary_per_flight DECIMAL(12,2) NOT NULL DEFAULT 0.00,
  daily_retainer DECIMAL(12,2) NOT NULL DEFAULT 0.00,
  revenue_share_percent DECIMAL(5,2) NOT NULL DEFAULT 0.00,
  currency_code CHAR(3) NOT NULL DEFAULT 'EUR',

  morale_score TINYINT UNSIGNED NOT NULL DEFAULT 70,
  fatigue_score TINYINT UNSIGNED NOT NULL DEFAULT 0,

  hired_at_utc TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  dismissed_at_utc TIMESTAMP NULL,

  PRIMARY KEY (id),
  KEY idx_company_staff_company_role (company_id, staff_role, employment_status),
  KEY idx_company_staff_base (assigned_base_icao_code),
  KEY idx_company_staff_source_candidate (source_candidate_id),

  CONSTRAINT fk_company_staff_company
    FOREIGN KEY (company_id)
    REFERENCES companies(id)
    ON UPDATE CASCADE
    ON DELETE CASCADE,

  CONSTRAINT fk_company_staff_source_candidate
    FOREIGN KEY (source_candidate_id)
    REFERENCES staff_candidates(id)
    ON UPDATE CASCADE
    ON DELETE SET NULL,

  CONSTRAINT fk_company_staff_base
    FOREIGN KEY (assigned_base_icao_code)
    REFERENCES airports(icao_code)
    ON UPDATE CASCADE
    ON DELETE RESTRICT,

  CONSTRAINT chk_company_staff_role
    CHECK (staff_role IN ('PILOT', 'TECHNICIAN')),

  CONSTRAINT chk_company_staff_status
    CHECK (employment_status IN ('ACTIVE', 'SUSPENDED', 'TRAINING', 'ON_LEAVE', 'DISMISSED')),

  CONSTRAINT chk_company_staff_scores
    CHECK (
      fear_score BETWEEN 0 AND 100
      AND courage_score BETWEEN 0 AND 100
      AND stress_tolerance_score BETWEEN 0 AND 100
      AND discipline_score BETWEEN 0 AND 100
      AND teamwork_score BETWEEN 0 AND 100
      AND reliability_score BETWEEN 0 AND 100
      AND ambition_score BETWEEN 0 AND 100
      AND fatigue_risk_score BETWEEN 0 AND 100
      AND morale_score BETWEEN 0 AND 100
      AND fatigue_score BETWEEN 0 AND 100
    ),

  CONSTRAINT chk_company_staff_currency
    CHECK (currency_code IN ('EUR', 'USD')),

  CONSTRAINT chk_company_staff_compensation
    CHECK (
      salary_per_flight >= 0
      AND daily_retainer >= 0
      AND revenue_share_percent BETWEEN 0 AND 100
    )
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS company_staff_licenses (
  company_staff_id BIGINT UNSIGNED NOT NULL,
  license_code VARCHAR(50) NOT NULL,
  proficiency_score TINYINT UNSIGNED NOT NULL DEFAULT 70,
  issued_at_utc TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  expires_at_utc TIMESTAMP NULL,
  PRIMARY KEY (company_staff_id, license_code),
  KEY idx_company_staff_licenses_license (license_code),

  CONSTRAINT fk_company_staff_licenses_staff
    FOREIGN KEY (company_staff_id)
    REFERENCES company_staff(id)
    ON UPDATE CASCADE
    ON DELETE CASCADE,

  CONSTRAINT fk_company_staff_licenses_license
    FOREIGN KEY (license_code)
    REFERENCES staff_license_types(code)
    ON UPDATE CASCADE
    ON DELETE RESTRICT,

  CONSTRAINT chk_company_staff_licenses_proficiency
    CHECK (proficiency_score BETWEEN 0 AND 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

