CREATE OR REPLACE VIEW v_staff_candidates_available AS
SELECT
  c.id AS candidate_id,
  c.first_name,
  c.last_name,
  c.display_name,
  c.staff_role,
  c.status,
  c.home_region_code,
  c.preferred_base_icao_code,
  c.age_years,
  c.experience_level,
  c.fear_score,
  c.courage_score,
  c.stress_tolerance_score,
  c.discipline_score,
  c.teamwork_score,
  c.reliability_score,
  c.ambition_score,
  c.fatigue_risk_score,
  c.flight_hours_total,
  c.aircraft_maintenance_hours_total,
  c.salary_per_flight,
  c.daily_retainer,
  c.revenue_share_percent,
  c.currency_code,
  c.hiring_bonus,
  c.morale_score,
  GROUP_CONCAT(CONCAT(l.code, ':', scl.proficiency_score) ORDER BY l.code SEPARATOR ', ') AS licenses_summary
FROM staff_candidates c
LEFT JOIN staff_candidate_licenses scl
  ON scl.candidate_id = c.id
LEFT JOIN staff_license_types l
  ON l.code = scl.license_code
WHERE c.status = 'AVAILABLE'
GROUP BY
  c.id,
  c.first_name,
  c.last_name,
  c.display_name,
  c.staff_role,
  c.status,
  c.home_region_code,
  c.preferred_base_icao_code,
  c.age_years,
  c.experience_level,
  c.fear_score,
  c.courage_score,
  c.stress_tolerance_score,
  c.discipline_score,
  c.teamwork_score,
  c.reliability_score,
  c.ambition_score,
  c.fatigue_risk_score,
  c.flight_hours_total,
  c.aircraft_maintenance_hours_total,
  c.salary_per_flight,
  c.daily_retainer,
  c.revenue_share_percent,
  c.currency_code,
  c.hiring_bonus,
  c.morale_score;

CREATE OR REPLACE VIEW v_company_staff AS
SELECT
  s.id AS company_staff_id,
  s.company_id,
  co.company_name,
  s.first_name,
  s.last_name,
  s.display_name,
  s.staff_role,
  s.employment_status,
  s.assigned_base_icao_code,
  s.age_years,
  s.experience_level,
  s.fear_score,
  s.courage_score,
  s.stress_tolerance_score,
  s.discipline_score,
  s.teamwork_score,
  s.reliability_score,
  s.ambition_score,
  s.fatigue_risk_score,
  s.flight_hours_total,
  s.aircraft_maintenance_hours_total,
  s.salary_per_flight,
  s.daily_retainer,
  s.revenue_share_percent,
  s.currency_code,
  s.morale_score,
  s.fatigue_score,
  GROUP_CONCAT(CONCAT(l.code, ':', csl.proficiency_score) ORDER BY l.code SEPARATOR ', ') AS licenses_summary
FROM company_staff s
JOIN companies co
  ON co.id = s.company_id
LEFT JOIN company_staff_licenses csl
  ON csl.company_staff_id = s.id
LEFT JOIN staff_license_types l
  ON l.code = csl.license_code
GROUP BY
  s.id,
  s.company_id,
  co.company_name,
  s.first_name,
  s.last_name,
  s.display_name,
  s.staff_role,
  s.employment_status,
  s.assigned_base_icao_code,
  s.age_years,
  s.experience_level,
  s.fear_score,
  s.courage_score,
  s.stress_tolerance_score,
  s.discipline_score,
  s.teamwork_score,
  s.reliability_score,
  s.ambition_score,
  s.fatigue_risk_score,
  s.flight_hours_total,
  s.aircraft_maintenance_hours_total,
  s.salary_per_flight,
  s.daily_retainer,
  s.revenue_share_percent,
  s.currency_code,
  s.morale_score,
  s.fatigue_score;

SELECT staff_role, COUNT(*) AS available_candidates
FROM staff_candidates
WHERE status = 'AVAILABLE'
GROUP BY staff_role;

COMMIT;
